const MobileNav = ({ active, setActive }) => {
    const { coursesOpen, courses, isCoursePage, toggleCoursesDropdown } = useMobileNav(active);
    const { isAuthenticated, user, logout } = useAuth();
    const navigate = useNavigate();
    const isStudent = isAuthenticated && user?.role === "student";
    const close = () => setActive(false);

    const onLogout = async () => {
        close();
        await logout();
        navigate("/login");
    };

    return (
        <div className={cn('mobile-nav', 'container', active && 'active')} onClick={() => { setActive(prev => !prev) }}>
            <div className='mobile-nav-top'>
                <div className='mobile-nav-close-btn'>
                    <CloseIcon />
                </div>
            </div>
            {isStudent ? (
                <>
                    <ul className="mobile-nav-ul">
                        <li onClick={(e) => e.stopPropagation()}><Link to="/account" onClick={close}>Головна</Link></li>
                        <li onClick={(e) => e.stopPropagation()}><Link to="/account/courses" onClick={close}>Мої курси</Link></li>
                        <li onClick={(e) => e.stopPropagation()}><Link to="/account/schedule" onClick={close}>Розклад</Link></li>
                        <li onClick={(e) => e.stopPropagation()}>
                            <button type="button" className="mobile-nav-logout" onClick={onLogout}>
                                Вийти
                            </button>
                        </li>
                    </ul>
                    <div className='mobile-nav-bottom' onClick={(e) => e.stopPropagation()}>
                        <Toggler />
                    </div>
                </>
            ) : (
                <>
                    <ul className="mobile-nav-ul">
                        <li><HashLink to="/#hero">Головна</HashLink></li>
                        <li><HashLink to={isCoursePage ? "#about" : "/#features"}>Переваги</HashLink></li>
                        <li className={`mobile-nav-dropdown ${coursesOpen ? 'open' : ''}`}>
                            <div
                                className="mobile-nav-dropdown-toggle"
                                onClick={toggleCoursesDropdown}
                            >
                                <span>Курси</span>
                                <ChevronIcon />
                            </div>
                            <ul className="mobile-nav-dropdown-list">
                                {courses.map(({ id }) => (
                                    <li key={id}>
                                        <Link to={`/course/${id}`}>{capitalize(id)}</Link>
                                    </li>
                                ))}
                            </ul>
                        </li>
                        <li><a href="#responses">Відгуки</a></li>
                        <li onClick={(e) => e.stopPropagation()}>
                            {isStudent ? (
                                <Link to="/account">{user?.display_name || 'Акаунт'}</Link>
                            ) : (
                                <Link to="/login">Увійти</Link>
                            )}
                        </li>
                    </ul>
                    <div className='mobile-nav-bottom'>
                        <PhoneIcon className="phone-icon" />
                        <Button text={'+380 50 600 60 94'} link={'+380 50 600 60 94'} classes={'btn-course step-2 mobile-nav-btn'} />
                        <div onClick={(e) => e.stopPropagation()}>
                            <Toggler />
                        </div>
                    </div>
                </>
            )}
        </div>
    )
}



export default MobileNav
